record Point(long x, long y) {}
static Point last;

static long escaping(int n) {
    long sum = 0;
    for (int i = 0; i < n; i++) {
        Point p = new Point(i, i * 2L);
        if ((i & 0xFFFFF) == 0) last = p; // khoảng một triệu vòng mới thoát một lần
        sum += p.x();
    }
    return sum;
}
